INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c302-7a81-a885-9acb954dc9b5'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Explain why sqrt(3) is irrational.', 'sqrt(3) cannot be expressed as a fraction p/q where p and q are integers and q is not zero.', 'An irrational number cannot be written in the form p/q in lowest terms. sqrt(3) is not a perfect square, so it is irrational.', 'Easy', '{"tags":"sass-2022-p1,q3b","subtopic":"Irrational numbers","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.090Z'::timestamptz, '2026-09-03T15:48:09.090Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c326-7bf3-b9bf-3ecfa07f2d07'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'The length of a road is 385 m. Maria runs along this road at an average speed of 3.9 m/s. This speed is correct to 1 decimal place.

Calculate the greatest possible time taken by Maria.', '100 s', 'Greatest time uses the lower bound of speed.
Lower bound of 3.9 m/s (1 d.p.) = 3.85 m/s.
Time = distance / speed = 385 / 3.85 = 100 s.', 'Medium', '{"tags":"sass-2022-p1,q4","subtopic":"Upper and lower bounds","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.126Z'::timestamptz, '2026-09-03T15:48:09.126Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c33d-74e1-aee0-bc7d2376fdeb'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Solve the inequality

2(5 - x) <= 3x < 37 - 5x.', '2 <= x < 37/8', 'Split the inequality:
2(5 - x) <= 3x => 10 - 2x <= 3x => 10 <= 5x => x >= 2.
3x < 37 - 5x => 8x < 37 => x < 37/8.
So 2 <= x < 37/8.', 'Medium', '{"tags":"sass-2022-p1,q6a","subtopic":"Compound inequalities","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.149Z'::timestamptz, '2026-09-03T15:48:09.149Z'::timestamptz) ON CONFLICT (id) DO NOTHING;